statement:
One table logs subscription changes:

- `subscription_events(event_id, user_id, event_date, event_type, plan_name, monthly_amount)`: one row per event; `event_id` is unique. `event_type` is `'start'`, `'upgrade'`, `'downgrade'` or `'cancel'`. `plan_name` is `'basic'`, `'standard'` or `'premium'`, and `null` for a cancel. `monthly_amount` is what the user pays per month after the event: positive, and `0` for a cancel. A user never has two events on the same date.

A user's **last event** is the one with their latest `event_date`. A user is a **churn risk** when all of these hold:

- their last event is not a `cancel`;
- they have at least one `downgrade` event;
- the `monthly_amount` of their last event is strictly less than half of the largest `monthly_amount` among all their events;
- the number of days from their first event to their last event is at least 60.

For each churn-risk user report `user_id`, `current_plan` (the plan of the last event), `current_monthly_amount` (its amount), `max_historical_amount` (their largest amount) and `days_as_subscriber` (days from first to last event). Sort by `days_as_subscriber` descending, then by `user_id` ascending.

validator:
function validate(input) {
  const [{ subscription_events = [] }] = input;
  const ids = new Set(), days = new Set();
  for (const [id, user, day, type, plan, amount] of subscription_events) {
    if ([id, user, day, type, amount].includes(null)) return 'Only plan_name may be null.';
    if (ids.has(id)) return `event_id ${id} appears twice.`;
    ids.add(id);
    if (!['start', 'upgrade', 'downgrade', 'cancel'].includes(type)) return `event_type ${type} is not a known event type.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) return `event_date ${day} must look like 2024-01-31.`;
    if (days.has(`${user}|${day}`)) return `User ${user} has two events on ${day}.`;
    days.add(`${user}|${day}`);
    if (type === 'cancel') {
      if (plan !== null || amount !== 0) return `Cancel event ${id} must have a null plan and a 0 amount.`;
    } else {
      if (!['basic', 'standard', 'premium'].includes(plan)) return `plan_name ${plan} must be basic, standard or premium.`;
      if (!(amount > 0)) return `Event ${id} needs a positive monthly_amount.`;
    }
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const pad = n => String(n).padStart(2, '0');
  const date = offset => { const d = new Date(Date.UTC(2024, 0, 1 + offset)); return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`; };
  const plans = ['basic', 'standard', 'premium'];
  // Two price lists: with whole prices standard -> basic is exactly half; with .99 prices it is just under half.
  const priceLists = [[9.99, 19.99, 29.99], [10, 20, 30], [12, 25, 40]];
  const gaps = small ? [5, 15, 29, 30, 31, 45] : [3, 10, 20, 30, 45, 60];
  const subscription_events = [];
  const users = small ? 1 + Math.floor(rand() * 3) : 250;
  let budget = small ? Math.floor(rand() * 9) : 2000;
  for (let u = 0; u < users && budget > 0; u++) {
    const user = small ? 501 + u : 1000 + u;
    const prices = pick(priceLists);
    const events = u === users - 1 ? budget : Math.min(budget, small ? 1 + Math.floor(rand() * 5) : 2 + Math.floor(rand() * 13));
    budget -= events;
    let day = small ? pick([0, 10, 20]) : Math.floor(rand() * 60), level = -1;
    for (let e = 0; e < events; e++) {
      let type;
      if (level < 0) type = 'start';
      else if (rand() < 0.12) type = 'cancel';
      else if (level === 0) type = 'upgrade';
      else if (level === 2) type = 'downgrade';
      else type = rand() < 0.5 ? 'upgrade' : 'downgrade';
      if (type === 'start') level = Math.floor(rand() * 3);
      else if (type === 'upgrade') level += 1 + (level === 0 && rand() < 0.4 ? 1 : 0);
      else if (type === 'downgrade') level -= 1 + (level === 2 && rand() < 0.5 ? 1 : 0);
      else level = -1;
      const row = level < 0 ? [null, 0] : [plans[level], prices[level]];
      subscription_events.push([subscription_events.length + 1, user, date(day), type, ...row]);
      day += pick(gaps);
    }
  }
  // Shuffle so that event_id order does not follow the dates.
  for (let i = subscription_events.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [subscription_events[i], subscription_events[j]] = [subscription_events[j], subscription_events[i]];
  }
  subscription_events.forEach((row, i) => { row[0] = i + 1; });
  return [{ subscription_events }];
}
